private static SchemaApi.IterableTypeValue iterableValueToProto(FieldType elementType, Iterable values) {
  try {
    return IterableTypeValue.newBuilder()
        .addAllElement(Iterables.transform(values, e -> fieldValueToProto(elementType, e)))
        .build();
  } catch (RuntimeException e) {
    // Log the exception or handle it as needed
    throw e; // Rethrow or handle as appropriate
  }
}
